#include <algorithm>
#include <cstdlib>
#include <fstream>
#include <vector>

struct FencePoint { long long x, y; };

long long largestTwiceArea(const std::vector<FencePoint>& posts) {
    long long answer = 0;
    for (const FencePoint& corner : posts) {
        long long horizontal = 0, vertical = 0;
        for (const FencePoint& other : posts) {
            if (other.y == corner.y)
                horizontal = std::max(horizontal, std::llabs(other.x - corner.x));
            if (other.x == corner.x)
                vertical = std::max(vertical, std::llabs(other.y - corner.y));
        }
        answer = std::max(answer, horizontal * vertical);
    }
    return answer;
}

int main() {
    std::ifstream in("triangles.in");
    std::ofstream out("triangles.out");
    int n;
    in >> n;
    std::vector<FencePoint> posts(n);
    for (auto& point : posts) in >> point.x >> point.y;
    out << largestTwiceArea(posts) << '\n';
    return 0;
}
