#include <string>

int minimumBreedFlips(const std::string& wanted, const std::string& actual) {
    int answer = 0;
    bool previousMismatch = false;
    for (std::size_t i = 0; i < wanted.size(); ++i) {
        bool mismatch = wanted[i] != actual[i];
        if (mismatch && !previousMismatch) ++answer;
        previousMismatch = mismatch;
    }
    return answer;
}

int main() {
    std::ifstream in("breedflip.in");
    std::ofstream out("breedflip.out");
    int n;
    std::string wanted, actual;
    in >> n >> wanted >> actual;
    out << minimumBreedFlips(wanted, actual) << '\n';
