#include <algorithm>
#include <fstream>
#include <numeric>
#include <vector>

std::vector<int> finalSwapOrder(int n, long long repeats,
                              int a1, int a2, int b1, int b2) {
    std::vector<int> power(n), answer(n);
    std::iota(power.begin(), power.end(), 0);
    std::iota(answer.begin(), answer.end(), 0);
    std::reverse(power.begin() + a1 - 1, power.begin() + a2);
    std::reverse(power.begin() + b1 - 1, power.begin() + b2);
    while (repeats > 0) {
        if (repeats & 1LL) {
            for (int i = 0; i < n; ++i) answer[i] = power[answer[i]];
        }
        std::vector<int> next(n);
        for (int i = 0; i < n; ++i) next[i] = power[power[i]];
        power.swap(next);
        repeats /= 2;
    }
    for (int& label : answer) ++label;
    return answer;
}

int main() {
    std::ifstream in("swap.in");
    std::ofstream out("swap.out");
    int n, a1, a2, b1, b2;
    long long repeats;
    in >> n >> repeats >> a1 >> a2 >> b1 >> b2;
    for (int label : finalSwapOrder(n, repeats, a1, a2, b1, b2))
        out << label << '\n';
    return 0;
}
